in another instance of yourself, you gave me this answer:

To handle three possible combinations (add element, edit element, or delete elements) in the Game event, you can modify the ChildFrameClosedEvent class to include an additional member variable indicating the action type. Here’s an updated example:

// Forward declaration of the Game class
class Game;

// Enum type for the action
enum class ActionType
{
    Add,
    Edit,
    Delete
};

// Custom event class
class ChildFrameClosedEvent : public wxEvent
{
public:
    ChildFrameClosedEvent(wxEventType eventType = wxEVT_NULL, int id = 0)
        : wxEvent(id, eventType), m_actionType(ActionType::Add) {}

    // Setter and getter for the Game object
    void SetGame(Game* game) { m_game = game; }
    Game* GetGame() const { return m_game; }

    // Setter and getter for the action type
    void SetActionType(ActionType actionType) { m_actionType = actionType; }
    ActionType GetActionType() const { return m_actionType; }

    // Required for copying the event object
    wxEvent* Clone() const override { return new ChildFrameClosedEvent(this); }

private:
    Game m_game;         // Game object
    ActionType m_actionType; // Action type
};

// Child frame class
class ChildFrame : public wxFrame
{
public:
    ChildFrame(wxFrame* parent, const wxString& title)
        : wxFrame(parent, wxID_ANY, title) {}

    void OnClose(wxCloseEvent& event)
    {
        // Create a new Game object
        Game* newGame = new Game();

        // Create a custom event and set the Game object
        ChildFrameClosedEvent customEvent(wxEVT_NULL);
        customEvent.SetGame(newGame);

        // Set the action type based on the specific scenario
        customEvent.SetActionType(ActionType::Add); // Replace with the desired action type

        // Post the event to the parent frame
        if (GetParent())
            wxPostEvent(GetParent(), customEvent);

        event.Skip();
    }
};

// Parent frame class
class ParentFrame : public wxFrame
{
public:
    ParentFrame(const wxString& title)
        : wxFrame(nullptr, wxID_ANY, title)
    {
    }

    void OnChildFrameClosed(wxCommandEvent& event)
    {
        // Get the custom event object
        ChildFrameClosedEvent* customEvent = dynamic_cast<ChildFrameClosedEvent*>(&event);
        if (customEvent)
        {
            // Get the Game object from the event
            Game* game = customEvent->GetGame();

            // Get the action type from the event
            ActionType actionType = customEvent->GetActionType();

            // Perform the action based on the action type
            switch (actionType)
            {
                case ActionType::Add:
                    // Handle adding element
                    break;
                case ActionType::Edit:
                    // Handle editing element
                    break;
                case ActionType::Delete:
                    // Handle deleting element
                    break;
                default:
                    break;
            }

            // Clean up the Game object
            delete game;
        }
    }
};

