public class CurrentDataRepository {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    public List<Double> findCurrentData(Long inverterId, String dataType, String timeRange) {
        // 使用JdbcTemplate执行SQL查询，并返回支路电流数据

        // 例子：
        String sql = “SELECT current_value FROM current_data WHERE inverter_id = ? AND data_type = ? AND time_range = ?”;
                // 执行查询，将结果映射为List<Double>
        List<Double> currentData = jdbcTemplate.queryForList(sql, Double.class, inverterId, dataType, timeRange);
        return currentData;
    }
}

