  <div class='container'>
    <h1 style='color: white; margin-top: 20px;'>T2I UI</h1>
    <div class='control-container'>
      <input id='inputText' type='text' value='Astronaut riding a horse' class='input-field'>
      <button onclick='generateImage()' style='margin: 10px;'>Generate Image</button>
      <div>
        <input type='checkbox' id='autoQueueCheckbox'>
        <label for='autoQueueCheckbox'>Auto Queue</label>
      </div>
      <div>
        <label for='retryAttemptsInput'>Retry Attempts:</label>
        <input type='number' id='retryAttemptsInput' value='5' min='1'>
      </div>
    </div>
