}

.control-container {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: flex-start;
  margin: 0;
}

.input-field-container {
  position: absolute;
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: center; 
}

.input-field {
display:flex;
width: 100%;
height: 32px;
box-sizing: border-box;
background-color:#010130;
color:#aa50ff;
border:1px solid darkmagenta;
border-radius:6px;
padding:5px;
align-items: center;
justify-content: center;
font-size: var(--font-size, 16px);
font-family: var(--font-family, monospace);
font-weight: var(--font-weight, bold);
-webkit-text-stroke: 1px rgba(139, 0, 139, 0.5);
text-stroke: 1px rgba(139, 0, 139, 1);
}

.gen-button-container {
  position: relative;
}

.gen-button {
  margin: 0;
  background: radial-gradient(circle at top center, #929, #519);
  color: white;
  border-radius: 6px;
  padding: 2px;
  font-size: var(--font-size, 16px);
  --font-family: var(--font-family, monospace);
  --font-weight: var(--font-weight, bold);
  -webkit-text-stroke: 1px rgba(139, 0, 139, 0.5); 
  text-stroke: 1px rgba(139, 0, 139, 1);
  text-shadow: 0px 0px 0.1px rgba(255, 255, 255, 1);
}

.image-canvas {
  display: flex;
  align-items: center;
  position: relative;
  width: 100%;
  background: linear-gradient(to right, darkmagenta 1px, transparent 1px) 0 0,
              linear-gradient(to right, darkmagenta 1px, transparent 1px) 0 100%,
              linear-gradient(to top, darkmagenta 1px, transparent 1px) 0 0,
              linear-gradient(to top, darkmagenta 1px, transparent 1px) 100% 0;
  background-size: 25% 100%, 25% 200px, 100% 25%, 100% 25%;
  background-repeat: repeat-x, repeat-x, repeat-y, repeat-y;
  background-position: top left, bottom left, top left, top right;
  background-color: #010130;
  border-style: double dashed;
  border-width: 2px;
  border-color: darkmagenta;
  z-index: 1;
}

.image-canvas:before {
  content: '';
  position: relative;
  top: 2px;
  left: 2px;
  width: calc(100% - 4px);
  height: calc(100% - 4px);
  background-color: #010130;
  z-index: -1;
}
.canvas-container {
  position: relative;
  width: 100%;
  max-width: 100%;
  height: calc(100vw / 50vh);
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: center;
  background-color: transparent;
  z-index: 2;
}
.progress-bar {
  position: relative;
  width: calc(100% - 100px);
  height: 2px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: flex-start;
  background-color: black;
}

.progress-bar-filled {
  width: 0%;
  height: 10px;
  background-color: green;
}

.independent-container {
  width: 100%;
  position:relative;
  display: flex;
  flex-wrap: wrap;
