      clearInterval(interval);
      progressBarFilled.style.width = '100%';
      progressBarFilled.style.backgroundColor = 'darkmagenta';
      break;
    } catch (error) {
      console.error(error);
      retryAttempts++;
    }

    if (autoQueueActive) {
