import UIKit
import Combine

enum ElementsOfProductCard: String {
    case priceInOtherStoresCell
}

final class ProductCardViewController: UIViewController {


    // MARK: - Private Properties
    private let screenWidth = (UIScreen.main.bounds.size.width)
    private let screenHeight = (UIScreen.main.bounds.size.height)
    private var cancellable = Set<AnyCancellable>()
    private var popularProducts: [ProductModel] = []

    private var elementsOfProductCard: [ElementsOfProductCard] = [
        .priceInOtherStoresCell]

    var basketCache = [String: Int]()
    var favoritesCache = [String]()
    private var timer: Timer?
    // MARK: - Properties
    var storeAllName: [SearchHitSourceStore] = []
    var product: ProductModel
    let productCardView: ProductCardView
    let viewModel: ProductCardViewModel

    // MARK: - Init
    init(product: ProductModel, viewModel: ProductCardViewModel, view: ProductCardView) {
        self.productCardView = view
        self.product = product
        self.viewModel = viewModel
        self.storeAllName = product.storeAllName
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    // MARK: - Lifecycle
    override func loadView() {
        super.loadView()
        self.view = productCardView
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        getModelsFromApi()
        setupBindings()
        setupView()
        setupCacheBindings()
        addTargets()
    }

    override func viewWillAppear(_ animated: Bool) {
        super.viewWillAppear(animated)
        navigationController?.navigationBar.isHidden = true
        fetchBasketCache()
        fetchFavoritesCache()
    }

    // MARK: - Private API
    private func getModelsFromApi() {
        viewModel.getAllPopularProducts(id: product.uuidProductInStore)
    }


    private func setupBindings() {
        productCardView.customNavigationBar.backButton.tapPublisher.sink(receiveValue: { [weak self] in
            self?.viewModel.isFinishScreen?()
        }).store(in: &cancellable)

        viewModel.popularProducts.sink(receiveValue: { popularProducts in
            self.popularProducts = popularProducts
            self.productCardView.recommendedProductView.popularProducts = popularProducts
            self.productCardView.recommendedProductView.collectionView.reloadData()
        }).store(in: &cancellable)
    }

    private func addTargets() {
        let tapgesture = UITapGestureRecognizer(target: self, action: #selector(imageTapped))
                tapgesture.numberOfTapsRequired = 1
                self.productCardView.imageFoodView.addGestureRecognizer(tapgesture)
                self.productCardView.imageFoodView.isUserInteractionEnabled = true
    }

    private func setupView() {
        productCardView.customNavigationBar.title = product.category ?? ""
        view.backgroundColor = Asset.Colors.backgroundGray.color
        productCardView.configureProductImageView(product: self.product, onTapHeartButton: { isFavorite in
            self.product.isFavourite = isFavorite
                     let productId = self.product.uuidProduct
                     switch isFavorite {
                     case true:
                         self.viewModel.addToFavorite(product: productId)
                     case false:
                         self.viewModel.removeFromFavorite(product: productId)
                     }
        })

    }

    @objc func imageTapped(_ sender: UITapGestureRecognizer) {
        guard let imageView = sender.view as? UIImageView else { return }
        let newImageView = UIImageView(image: imageView.image)
        newImageView.frame = UIScreen.main.bounds
        newImageView.backgroundColor = Asset.Colors.white.color
        newImageView.contentMode = .scaleAspectFit
        newImageView.isUserInteractionEnabled = true
        let tap = UITapGestureRecognizer(target: self, action: #selector(dismissFullscreenImage))
        newImageView.addGestureRecognizer(tap)
        self.view.addSubview(newImageView)
        self.navigationController?.isNavigationBarHidden = true
        self.tabBarController?.tabBar.isHidden = true
    }

    @objc func dismissFullscreenImage(_ sender: UITapGestureRecognizer) {
        self.navigationController?.isNavigationBarHidden = true
        self.tabBarController?.tabBar.isHidden = false
        sender.view?.removeFromSuperview()
    }
}

