                let height = screenWidth - 20
                return CGSize(width: screenWidth, height: height)
            case 1: let height: CGFloat = CGFloat(self.storeAllName.count*50) + CGFloat((self.storeAllName.count+1)*16)
                return CGSize(width: screenWidth, height: height)
            case 2: return CGSize(width: screenWidth, height: 269)

            default:
                return CGSize(width: screenWidth, height: 420)
            }
        }
    }

