@Mod(modid = DoomMod.MODID, name = DoomMod.NAME, version = DoomMod.VERSION)
public class DoomMod {

    public static final String MODID = "doommod";
    public static final String NAME = "DOOM Mod";
    public static final String VERSION = "1.0";

    private int currentFrame = 0;
    private static final int NUM_FRAMES = 3;
    private static final int FRAME_WIDTH = 64;
    private static final int FRAME_HEIGHT = 64;
    private static final int ANIMATION_SPEED = 10;

    public DoomMod() {
        FMLJavaModLoadingContext.get().getModEventBus().register(this);
    }

    @SubscribeEvent
    public void onRenderGameOverlay(RenderGameOverlayEvent event) {
        if (event.getType() == ElementType.TEXT) {
            Minecraft mc = Minecraft.getInstance();
            FontRenderer fontRenderer = mc.fontRenderer;

            int frameX = currentFrame * FRAME_WIDTH;
            int frameY = 0;

            ResourceLocation textureLocation = getFrameTexture(currentFrame);
            RenderSystem.setShaderTexture(0, textureLocation);
            RenderSystem.enableBlend();
            RenderSystem.defaultBlendFunc();

            int screenWidth = mc.getMainWindow().getScaledWidth();
            int screenHeight = mc.getMainWindow().getScaledHeight();

            int xOffset = screenWidth / 2 - FRAME_WIDTH / 2;
            int yOffset = screenHeight - FRAME_HEIGHT;

            mc.ingameGUI.blit(xOffset, yOffset, 0, 0, FRAME_WIDTH, FRAME_HEIGHT);

            int health = (int) mc.player.getHealth();
            int armor = mc.player.getTotalArmorValue();

            fontRenderer.drawStringWithShadow("Health: " + health, 10, 10, 0xFF0000);
            fontRenderer.drawStringWithShadow("Armor: " + armor, 10, 20, 0x00FF00);

            ItemStack currentItemStack = mc.player.getHeldItemMainhand();
            if (!currentItemStack.isEmpty()) {
                String itemName = currentItemStack.getDisplayName();
                int ammoCount = 64;

                fontRenderer.drawStringWithShadow("Ammo: " + ammoCount, 10, 30, 0xFFFF00);
                fontRenderer.drawStringWithShadow("Weapon: " + itemName, 10, 40, 0xFFFFFF);
            }

            RenderHelper.enableStandardItemLighting();
            RenderSystem.disableBlend();

            currentFrame = (currentFrame + 1) % NUM_FRAMES;
        }
    }

    private ResourceLocation getFrameTexture(int frameIndex) {
        return new ResourceLocation(MODID, "textures/hud/face/face-" + frameIndex + ".png");
    }
}
